vec2 random2(vec2 p) {
    return fract(sin(vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)))) * 43758.5453);
}

float mhdistance(vec2 p1, vec2 p2) {
    return abs(p1.x - p2.x) + abs(p1.y - p2.y);
}

vec2 voronoi(vec2 st) {
// Tile the space
    vec2 i_st = floor(st);
    vec2 f_st = fract(st);

    float m_dist = 1.0;
    float point_color = 0.0;
    float m_point;        // minimum point   

    for(int y = -1; y <= 1; y++) {
        for(int x = -1; x <= 1; x++) {
            vec2 neighbor = vec2(float(x), float(y));
            vec2 point = vec2(.5);
            point = random2(i_st + neighbor);
            point_color = random2(i_st + neighbor).x;
            point = 0.5 + 0.5 * sin(iTime + 6.2831 * point);
            vec2 diff = neighbor + point - f_st;
            float dist = length(diff);
            dist = mhdistance(f_st, neighbor + point);// using mahhatan distance
            if(dist < m_dist) {
                m_dist = dist;
                m_point = point_color;
            }
        }
    }
    return vec2(m_dist, m_point);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
     vec2 st = gl_FragCoord.xy / iResolution.xy;
    vec3 color = vec3(0.0);

    // Scale
    st *= 10. * sin(iTime * 0.1) + 5.;

    vec2 col = voronoi(st);
    //color = vec3(col.x);
    //color = vec3(col.y);
    color = 0.4 * cos(col.y * 7.432423) + vec3(.5, .27, 1.76);
    color += 1. - step(.03, col.x);
    fragColor = vec4(color, 1.0);
}
